jQuery(window).on("elementor/frontend/init",function(){elementorFrontend.hooks.addAction("frontend/element_ready/form.default",function(t){var d=t.data("id"),i=(window.dceFieldDescriptions||{})[d];!i||!i.fields||!i.fields.length||i.fields.forEach(function(e){if(e.position==="elementor-field-label")if(e.tooltip){var o=t.find(".elementor-field-group-"+e.custom_id+" .elementor-field-label");o.addClass("dce-tooltip").addClass("elementor-field-label-description");var a=e.tooltip_position||"top",n=jQuery('<span class="dce-tooltiptext dce-tooltip-'+a+'"></span>');n.html(e.description),o.append(n)}else{var o=t.find(".elementor-field-group-"+e.custom_id+" .elementor-field-label"),r=jQuery('<abbr class="elementor-field-label-description elementor-field-label-description-'+e.custom_id+'"></abbr>');r.attr("title",e.description_text),o.wrap(r)}else if(e.position==="elementor-field"){var s=t.find(".elementor-field-group-"+e.custom_id),l=jQuery('<div class="elementor-field-input-description elementor-field-input-description-'+e.custom_id+'"></div>');l.html(e.description),s.append(l)}})})});
